import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
// Library: none — native interpolate with De Casteljau math for precise tip tracking



export type HandDrawnArrowProps = Record<string, any>;

const HandDrawnArrow: React.FC<HandDrawnArrowProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 2,
  arrowColor = "#ff2a5f", // Vibrant marker pink-red
  arrowThickness = 12, // More elegant marker-like stroke
  scale = 1.0, // Reduced default size for better layout fit
  rotation = 0,
  xOffset = 0,
  yOffset = 0,
  drawDurationFrames = 25, // Snappy yet organic draw
  delayFrames = 10,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Swooping, upward-pointing curve coordinates
  const x0 = -120 * s;  const y0 = 140 * s;  // Start at bottom-left
  const x1 = -40 * s;   const y1 = 150 * s;  // Swoop slightly down/right
  const x2 = 80 * s;    const y2 = 100 * s;  // Curve upward
  const x3 = 100 * s;   const y3 = -140 * s; // Shoot sharply up

  // Calculate drawing progress with a snappy ease-out curve
  const rawT = interpolate(
    frame,
    [delayFrames, delayFrames + drawDurationFrames],
    [0, 1],
    { 
      extrapolateLeft: "clamp", 
      extrapolateRight: "clamp", 
      easing: Easing.out(Easing.bezier(0.16, 1, 0.3, 1)) 
    }
  );

  // Prevent NaN in tangent calculations exactly at t=0
  const t = Math.max(0.001, rawT);

  // De Casteljau math (Cubic Bezier) to find exact endpoint and partial path per frame
  const L = (a: number, b: number, tVal: number) => a + (b - a) * tVal;

  const ax = L(x0, x1, t), ay = L(y0, y1, t);
  const bx = L(x1, x2, t), by = L(y1, y2, t);
  const cx = L(x2, x3, t), cy = L(y2, y3, t);

  const dx = L(ax, bx, t), dy = L(ay, by, t);
  const ex = L(bx, cx, t), ey = L(by, cy, t);

  // Exact tip position for this frame
  const tipX = L(dx, ex, t);
  const tipY = L(dy, ey, t);

  // Rebuild the truncated path to the current tip
  const partialD = `M ${x0} ${y0} C ${ax} ${ay}, ${dx} ${dy}, ${tipX} ${tipY}`;

  // Calculate forward tangent angle from the last control segment
  const angle = Math.atan2(tipY - dy, tipX - dx) * (180 / Math.PI);

  // Size the arrowhead proportionally to the stroke thickness
  const headSize = 20 * s + (arrowThickness * s * 0.4);

  // Fully hidden before entrance frame
  const isVisible = frame >= delayFrames;

  // Organic edge displacement scale
  const displacementScale = Math.max(1.5, 5 * s);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      <div
        style={{
          position: "absolute",
          left: width / 2 + xOffset * s,
          top: height / 2 + yOffset * s,
          transform: `scale(${scale}) rotate(${rotation}deg)`,
          opacity: isVisible ? 1 : 0,
          transition: "none",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <svg
          width={400 * s}
          height={400 * s}
          viewBox={`${-200 * s} ${-200 * s} ${400 * s} ${400 * s}`}
          style={{ overflow: "visible", transition: "none" }}
        >
          <defs>
            {/* SVG Filter to create a rough, textured hand-drawn marker effect */}
            <filter id="marker-texture" x="-20%" y="-20%" width="140%" height="140%">
              <feTurbulence
                type="fractalNoise"
                baseFrequency="0.06"
                numOctaves="3"
                result="noise"
              />
              <feDisplacementMap
                in="SourceGraphic"
                in2="noise"
                scale={displacementScale}
                xChannelSelector="R"
                yChannelSelector="G"
              />
            </filter>
          </defs>

          {/* Wrapper with marker-texture filter and subtle translucency */}
          <g filter="url(#marker-texture)" style={{ opacity: 0.9, transition: "none" }}>
            {/* Arrow Body */}
            <path
              d={partialD}
              fill="none"
              stroke={arrowColor}
              strokeWidth={arrowThickness * s}
              strokeLinecap="round"
              strokeLinejoin="round"
              style={{ transition: "none" }}
            />
            
            {/* Arrowhead (Rider on the tip) */}
            <g transform={`translate(${tipX}, ${tipY}) rotate(${angle})`} style={{ transition: "none" }}>
              <path
                // Pointing forward along the local X axis
                d={`M ${-headSize} ${-headSize * 0.7} L 0 0 L ${-headSize} ${headSize * 0.7}`}
                fill="none"
                stroke={arrowColor}
                strokeWidth={arrowThickness * s}
                strokeLinecap="round"
                strokeLinejoin="round"
                style={{ transition: "none" }}
              />
            </g>
          </g>
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default HandDrawnArrow;